// CSD_RATIONALE_BEGIN
// Root-cause analysis of attempt 68 (7.3%) vs best (attempt 66, 53.3%):
// Attempt 68 replaced RegenerateUnitOnGroundingFailure with a plain ConstrainedStep
// loop AND removed the IsCompletePrefix break. The model hit EOS after a few tokens
// (avg 10.03 generated), producing truncated SQL like "SELECT " because hard parser
// masking with no grounding check allowed EOS early and the model's distribution
// favored stopping without a FROM clause. Syntax rate collapsed to 15.7%.
//
// Attempt 67 (52%) used ConstrainedStep with IsCompletePrefix break but no
// grounding: 1.3pp below attempt 66's RegenerateUnitOnGroundingFailure (53.3%).
// This confirms RegenerateUnitOnGroundingFailure provides a grounding benefit.
//
// The 53.3% ceiling leaves 138/300 as syntax-valid semantic mismatches—hard
// model-capability failures. To squeeze improvement, I'll increase the three
// controllable parameters in RegenerateUnitOnGroundingFailure:
//   maxRetries: 5 → 8  (more resampling chances per wrong identifier)
//   maxRollbackBudget: 50 → 80  (more budget to roll back long identifiers)
//   Phase 3 budget cap: 300 → 450  (covers 99%+ of Spider query lengths)
//   Phase 4 close budget: 120 → 150  (more room to reach completable state)
//
// Everything else is identical to attempt 66 (best): same guidance, same 5-step
// preamble, same Phase 2 OpenConstrainedSpan, same Phase 4 CloseConstrainedSpan/
// CloseSpanWithinBudget. Budget math: Phase1(5)+Phase2(1)+Phase3(450)+Phase4(150)
// = 606 max steps, comfortably within maxSteps=900.
// CSD_RATIONALE_END

// CSD_PROOF_SKETCH_BEGIN
// Invariant 1 (parser_validity):
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
// Phase 1 (unconstrained loop): Guard includes !insideConstrainedOut, so the
//   implication is vacuous throughout. The only true-flip is via RenderedEndsWith
//   on the accumulated generated output; at that point currentConstrainedOut := []
//   and IsValidPrefix([]) holds by the method precondition. An EOS break exits
//   with insideConstrainedOut unchanged (false), keeping the implication vacuous.
//
// Phase 2 (OpenConstrainedSpan): Runs only when !insideConstrainedOut. Its
//   postcondition sets insideConstrainedOut := true and currentConstrainedOut := [];
//   IsValidPrefix([]) holds by the method precondition. Invariant re-established.
//
// Phase 3 (RegenerateUnitOnGroundingFailure): Helper postcondition guarantees
//   resultConstrained is always parser.IsValidPrefix. We assign
//   currentConstrainedOut := resultConstrained, re-establishing the invariant.
//   insideConstrainedOut is unchanged (still true from Phase 2 or entry).
//
// Phase 4a (CloseConstrainedSpan): Sets insideConstrainedOut := false, making
//   the implication vacuously true; clears currentConstrainedOut := [].
//
// Phase 4b (CloseSpanWithinBudget): Postcondition directly guarantees
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut).
//
// Invariant 2 (progress): |generated| <= |generatedPrefix| + steps
//
// Phase 1: UnconstrainedStep costs +1 step; appends 0 (EOS) or 1 (non-EOS)
//   token. Both cases preserve |generated| <= |generatedPrefix| + steps.
//
// Phase 2: OpenConstrainedSpan costs +1 step, appends exactly 1 "<<" token.
//   |generated| + 1 <= |generatedPrefix| + steps + 1 = |generatedPrefix| + new_steps.
//
// Phase 3: Let old_gen = generated before Phase 3, old_cc = currentConstrainedOut.
//   stablePrefix = old_gen[0..|old_gen|-|old_cc|], so |stablePrefix| = |old_gen|-|old_cc|.
//   The helper's cost contract guarantees |resultConstrained| <= sqlBudget because
//   each helper step produces at most one visible token. Hence:
//   |new_generated| = |stablePrefix| + |resultConstrained|
//                   <= (|old_gen| - |old_cc|) + sqlBudget
//                   <= |old_gen| + sqlBudget
//                   <= |generatedPrefix| + old_steps + sqlBudget
//                   = |generatedPrefix| + new_steps.
//   Cap sqlBudget = min(remaining-1, 450) <= remaining-1 <= maxSteps - old_steps - 1
//   ensures new_steps <= maxSteps.
//
// Phase 4a: CloseConstrainedSpan costs +1 step, appends at most 1 ">>" token.
//   |generated| + 1 <= |generatedPrefix| + steps + 1 = |generatedPrefix| + new_steps.
// Phase 4b: CloseSpanWithinBudget postcondition |generatedOut| <= |generated| + closeBudget;
//   steps += closeBudget. Preserved by transitivity.
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

helpers.AppendTaskGuidance(lm, "Output SQL: <<query>> where query is a valid SQL SELECT statement using ONLY the exact table and column names from the provided schema. The SQL must be placed between << and >>. No explanation, no markdown, no aliases not in the schema.");

var steps: nat := 0;

// Phase 1: Short preamble (at most 5 steps) to let model emit "SQL: <<" naturally
while steps < maxSteps && steps < 5 && !insideConstrainedOut
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  var next := helpers.UnconstrainedStep(lm, prompt, generated);
  steps := steps + 1;
  if next == eosToken {
    break;
  } else {
    generated := generated + [next];
    if RenderedEndsWith(generated, "<<") {
      insideConstrainedOut := true;
      currentConstrainedOut := [];
    }
  }
}

// Phase 2: Force "<<" if not already inside constrained span
if !insideConstrainedOut && steps < maxSteps {
  var og, oi, oc := helpers.OpenConstrainedSpan(lm, generated);
  generated := og;
  insideConstrainedOut := oi;
  currentConstrainedOut := oc;
  steps := steps + 1;
}

// Phase 3: Schema-grounded SQL via RegenerateUnitOnGroundingFailure
// Budget capped at 450, maxRetries raised to 8, maxRollbackBudget raised to 80
// to improve schema-identifier grounding beyond attempt 66's 53.3%.
if insideConstrainedOut && steps < maxSteps {
  var remaining := maxSteps - steps;
  if remaining >= 2 {
    var sqlBudget: nat;
    if remaining - 1 <= 450 {
      sqlBudget := remaining - 1;
    } else {
      sqlBudget := 450;
    }
    var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
    var resultConstrained := helpers.RegenerateUnitOnGroundingFailure(
      lm, parser, constrainedPrompt, currentConstrainedOut, eosToken, sqlBudget, 8, 80
    );
    var stablePrefix := generated[..|generated| - |currentConstrainedOut|];
    generated := stablePrefix + resultConstrained;
    currentConstrainedOut := resultConstrained;
    steps := steps + sqlBudget;
  }
}

// Phase 4: Close the constrained span
if insideConstrainedOut && steps < maxSteps {
  if parser.IsCompletePrefix(currentConstrainedOut) {
    var cg, ci, cc := helpers.CloseConstrainedSpan(lm, parser, generated, currentConstrainedOut);
    generated := cg;
    insideConstrainedOut := ci;
    currentConstrainedOut := cc;
    steps := steps + 1;
  } else {
    var remaining := maxSteps - steps;
    var closeBudget: nat;
    if remaining <= 150 {
      closeBudget := remaining;
    } else {
      closeBudget := 150;
    }
    var cg, ci, cc := helpers.CloseSpanWithinBudget(
      lm, parser, prompt, generated, currentConstrainedOut, eosToken, closeBudget
    );
    generated := cg;
    insideConstrainedOut := ci;
    currentConstrainedOut := cc;
    steps := steps + closeBudget;
  }
}

cost := steps;

